cd /home/user && python3 -c "
import json, librosa
y, sr = librosa.load('/home/user/input.wav', sr=22050, mono=True)
dur = len(y)/sr
segs = json.load(open('/home/user/segments.json'))
print('Duration:', dur)
print('Num segments:', len(segs))
print('Distinct labels:', sorted(set(s['label'] for s in segs)))
# Validate constraints
import re
errors=[]
for s in segs:
    if not re.match(r'^[A-Z]\$', s['label']): errors.append(f'bad label {s}')
    if s['start']>=s['end']: errors.append(f'start>=end {s}')
    if s['end']-s['start']<=0.5: errors.append(f'dur<=0.5 {s}')
if abs(segs[0]['start'])>0.3: errors.append('first start off')
if abs(segs[-1]['end']-dur)>0.5: errors.append('last end off')
for i in range(len(segs)-1):
    gap = segs[i+1]['start']-segs[i]['end']
    if gap>0.3: errors.append(f'gap {gap} at {i}')
    if gap<-0.05: errors.append(f'overlap {gap} at {i}')
# label reuse
from collections import Counter
c=Counter(s['label'] for s in segs)
reused=[l for l,n in c.items() if n>1]
print('Reused labels:', reused)
if len(segs)<3: errors.append('<3 segments')
if len(set(s['label'] for s in segs))<2: errors.append('<2 distinct labels')
if not reused: errors.append('no reused label')
print('Sorted by start:', all(segs[i]['start']<=segs[i+1]['start'] for i in range(len(segs)-1)))
print('ERRORS:', errors if errors else 'NONE')
print(json.dumps(segs, indent=2))
" 2>&1

